"use client"

import { Collapsible as CollapsiblePrimitive } from "@base-ui/react/collapsible"

/** Playful console Collapsible: the Base UI root that shows and hides a panel. */
const Collapsible = CollapsiblePrimitive.Root

/** The control that opens and closes the panel; style it at the call site. */
const CollapsibleTrigger = CollapsiblePrimitive.Trigger

/** The panel that shows when the collapsible is open. */
const CollapsibleContent = CollapsiblePrimitive.Panel

export { Collapsible, CollapsibleTrigger, CollapsibleContent }
